example_solution:
package wordy

import (
	"strconv"
	"strings"
)

func Answer(q string) (a int, ok bool) {
	w := strings.Fields(q)
	if len(w) < 3 { // length check for first two words and last word
		return a, ok
	}
	if w[0] != "What" || w[1] != "is" { // first two words required
		return a, ok
	}
	w = w[2:]
	last := len(w) - 1
	wl := w[last]
	if wl[len(wl)-1] != '?' { // trailing ? required
		return a, ok
	}
	w[last] = wl[:len(wl)-1]
	a, err := strconv.Atoi(w[0]) // first word after preamble must be a number
	if err != nil {
		return a, ok
	}
	for i := 1; i < len(w); i++ { // remainder of q must alternate between op, number
		op := w[i]
		i++
		switch op {
		case "multiplied", "divided":
			if i == len(w) || w[i] != "by" { // length check, required word
				return a, ok
			}
			i++ // consume
		}
		if i == len(w) { // length check for operand
			return a, ok
		}
		x, err := strconv.Atoi(w[i]) // must be a number
		if err != nil {
			return a, ok
		}
		switch op { // apply operator
		case "plus":
			a += x
		case "minus":
			a -= x
		case "multiplied":
			a *= x
		case "divided":
			a /= x
		default: // valid operator not found
			return a, ok
		}
	}
	return a, true
}

test_code:
package wordy

import "testing"

func TestAnswer(t *testing.T) {
	for _, tc := range tests {
		t.Run(tc.description, func(t *testing.T) {
			actual, ok := Answer(tc.question)
			switch {
			case tc.expectError:
				if ok {
					t.Fatalf("Answer(%q) expected error, got: %d", tc.question, actual)
				}
			case !ok:
				t.Fatalf("Answer(%q) returned ok=%t, want: %d", tc.question, ok, tc.expected)
			case actual != tc.expected:
				t.Fatalf("Answer(%q) = %d, want: %d", tc.question, actual, tc.expected)
			}
		})
	}
}

// Benchmark combined time to answer all questions.
func BenchmarkAnswer(b *testing.B) {
	for range b.N {
		for _, test := range tests {
			Answer(test.question)
		}
	}
}
